const allowedTypes = new Set(['deployment.completed', 'health.failed', 'checkout.failed', 'manual.test']);
const allowedSources = new Set(['relaycart', 'manual.test']);
const allowedMetadata = new Set(['version', 'outcome', 'reason', 'deployment_id', 'order_id', 'correlation_id', 'environment', 'message', 'level', 'log_id', 'impact_scope', 'fixture_mode']);
const allowedFixtureModes = new Set(['timeout','http_failure','malformed_json','schema_invalid','unknown_evidence_ref']);
const out = [];
function bounded(value, max = 2000) {
  if (typeof value === 'string') return value.slice(0, max);
  if (typeof value === 'number' || typeof value === 'boolean') return value;
  return undefined;
}
function mapRelayCart(row) {
  const details = row.details && typeof row.details === 'object' ? row.details : {};
  const at = row.created_at || row.timestamp;
  const occurred = new Date(at);
  const id = String(row.id ?? details.log_id ?? '');
  if (!id || Number.isNaN(occurred.getTime())) return null;
  const metadata = {
    version: details.version, outcome: details.outcome, reason: details.reason,
    deployment_id: details.deployment_id, order_id: details.order_id,
    correlation_id: details.correlation_id, environment: details.environment,
    message: row.message, level: row.level, log_id: id
  };
  return {
    event_id: `relaycart:${id}:${occurred.toISOString()}`, source: 'relaycart',
    event_type: row.event_type, service: row.service,
    environment: details.environment || 'production-demo', occurred_at: occurred.toISOString(),
    correlation_hint: details.correlation_id || (details.deployment_id ? `deployment-${details.deployment_id}` : null),
    severity_hint: null, metadata
  };
}
function normalize(raw, mode) {
  const errors = [];
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return {valid:false, errors:['event must be a JSON object'], ingest_mode:mode};
  const event = {...raw};
  if (typeof event.event_id !== 'string' || event.event_id.length < 1 || event.event_id.length > 240) errors.push('event_id must be 1-240 characters');
  if (!allowedSources.has(event.source)) errors.push('source is unsupported');
  if (!allowedTypes.has(event.event_type)) errors.push('event_type is unsupported');
  if (typeof event.service !== 'string' || !event.service.trim() || event.service.length > 120) errors.push('service is required and must be at most 120 characters');
  if (typeof event.environment !== 'string' || !event.environment.trim() || event.environment.length > 80) errors.push('environment is required and must be at most 80 characters');
  const date = new Date(event.occurred_at);
  if (!event.occurred_at || Number.isNaN(date.getTime())) errors.push('occurred_at must be a valid timestamp');
  if (event.severity_hint != null && !['SEV-1','SEV-2','SEV-3'].includes(event.severity_hint)) errors.push('severity_hint must be null or SEV-1/2/3');
  if (event.metadata == null) event.metadata = {};
  if (typeof event.metadata !== 'object' || Array.isArray(event.metadata)) errors.push('metadata must be an object');
  const clean = {};
  if (event.metadata && typeof event.metadata === 'object' && !Array.isArray(event.metadata)) {
    for (const [key,value] of Object.entries(event.metadata)) {
      if (allowedMetadata.has(key)) { const v = bounded(value); if (v !== undefined) clean[key] = v; }
    }
  }
  if (clean.fixture_mode && (event.source !== 'manual.test' || !allowedFixtureModes.has(clean.fixture_mode))) errors.push('fixture_mode is restricted to the approved manual.test fixtures');
  if (clean.impact_scope && (event.source !== 'manual.test' || !['limited','important','complete_outage'].includes(clean.impact_scope))) errors.push('impact_scope is restricted to manual.test values');
  if (event.correlation_hint != null && (typeof event.correlation_hint !== 'string' || event.correlation_hint.length > 240)) errors.push('correlation_hint must be null or at most 240 characters');
  return {valid:errors.length===0, errors, ingest_mode:mode, ...(errors.length===0 ? {event:{...event, occurred_at:date.toISOString(), metadata:clean, correlation_hint:event.correlation_hint || clean.correlation_id || null}} : {})};
}
for (const item of $input.all()) {
  const root = item.json || {};
  const polling = Array.isArray(root.events);
  const mode = polling ? 'poll' : 'webhook';
  if (polling) {
    for (const row of root.events) {
      if (!row || !['deployment.completed','health.failed','checkout.failed'].includes(row.event_type)) continue;
      const event = mapRelayCart(row);
      if (!event) continue;
      const result = normalize(event, mode);
      if (result.valid) out.push({json:result});
    }
  } else {
    const raw = root.body ?? root;
    out.push({json:normalize(raw, mode)});
  }
}
return out;
